import {memberName} from './teams.js?v=20261010-member-fixes';
import {restrictionActive} from './restrictions.js?v=20261010-member-fixes';
import {ladderGiftLinks} from './ladder-gifts.js?v=20261021-gift-links';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const colours=['#4976b7','#d89445','#7b9a77','#aa79a9','#ca7475','#648c9d','#a79853','#818ac0','#cc925e','#6aab99','#a6816a','#a1718b'];
const approved=actor=>actor?.user_metadata?.status==='approved'&&!restrictionActive(actor.user_metadata);
function service(db){
  const rpc=async(name,args)=>{const requested=performance.now();if(!db)throw Error('Service unavailable');const{data,error}=await db.rpc(name,args);if(error)throw error;if(data?.server_time)data._clockOffset=Date.parse(data.server_time)-(Date.now()-(performance.now()-requested)/2);return data;};
  return {list:()=>rpc('list_marble_rooms'),create:(capacity,losers,map)=>rpc('create_marble_room',{p_capacity:capacity,p_losers:losers,p_map:map}),settings:(id,capacity,losers,map)=>rpc('update_marble_settings',{p_room:id,p_capacity:capacity,p_losers:losers,p_map:map}),duration:(id,seed,duration)=>rpc('report_marble_duration',{p_room:id,p_seed:seed,p_duration_ms:duration}),join:code=>rpc('join_marble_room',{p_code:code}),get:id=>rpc('get_marble_room',{p_room:id}),ready:(id,value)=>rpc('set_marble_ready',{p_room:id,p_ready:value}),leave:id=>rpc('leave_marble_room',{p_room:id})};
}
function settingsFields(capacity=4,losers=1,map=0){return `<div class="tool-fields"><label>참여 인원<select name="capacity">${Array.from({length:11},(_,i)=>`<option value="${i+2}" ${i+2===capacity?'selected':''}>${i+2}명</option>`).join('')}</select></label><label>꽝 인원<select name="losers">${Array.from({length:capacity-1},(_,i)=>`<option value="${i+1}" ${i+1===losers?'selected':''}>${i+1}명</option>`).join('')}</select></label><label>맵<select name="map">${['운명의 수레바퀴','BubblePop','Pot of greed','Yoru ni Kakeru'].map((name,index)=>`<option value="${index}" ${index===map?'selected':''}>${name}${index===3?' · 긴 코스':''}</option>`).join('')}</select></label></div>`;}
function bindCapacity(form){form.elements.capacity.onchange=()=>{const capacity=Number(form.elements.capacity.value),losers=Math.min(Number(form.elements.losers.value),capacity-1);form.elements.losers.innerHTML=Array.from({length:capacity-1},(_,i)=>`<option value="${i+1}" ${i+1===losers?'selected':''}>${i+1}명</option>`).join('');};}
function friendly(error){const message=error?.message||'';if(/Host required/.test(message))return '방장만 설정을 변경할 수 있습니다.';if(/Capacity below/.test(message))return '이미 입장한 인원보다 작게 설정할 수 없습니다.';if(/Room full/.test(message))return '대기방이 가득 찼습니다.';if(/already starting/.test(message))return '이미 시작한 게임입니다.';if(/Room not found|Room closed|membership required/.test(message))return '대기방이 종료되었거나 참가할 수 없습니다.';if(/Approved member/.test(message))return '로그인한 승인 회원만 참여할 수 있습니다.';if(/limit/.test(message))return '방 생성 횟수를 초과했습니다. 잠시 후 다시 시도해 주세요.';return '대기방을 갱신하지 못했어요. 연결 상태를 확인해 주세요.';}
export async function renderOnlineMarble(main,{db,actor,isCurrent=()=>true,onAuth=()=>{},signal,notify=()=>{},onFrame}={}){
  const api=service(db,actor);let current=null,busy=false,generation=0,clockOffset=0,boardKey='',boardData=null,stopEffects=()=>{},preparedKey='',preparedMovie=null,prepareTask=null,engine=null,clockRound=null;
  main.innerHTML=`<section class="tool-page ladder-room-page marble-room-page"><div class="board-heading"><div><h1>마블룰렛</h1></div></div><p class="form-error" id="room-error" role="alert"></p><div id="marble-lobby"></div><section id="marble-room" hidden></section></section>`;
  const root=main.querySelector('.marble-room-page'),find=selector=>root.querySelector(selector),alive=()=>isCurrent()&&!signal?.aborted&&main.contains(root);
  function error(message){find('#room-error').textContent=message;}
  function lobby(){find('#marble-lobby').innerHTML=!approved(actor)?'<div class="room-login"><strong>로그인하고 함께 참여하세요.</strong><p>승인된 회원이 입장해 모두 준비하면 게임이 시작됩니다.</p><button class="primary" id="room-login-button" type="button">로그인</button></div>':`<div class="room-lobby-grid"><div class="tool-card"><h2>대기방 만들기</h2><form id="room-create-form">${settingsFields()}<p class="form-note">방을 만든 회원이 방장입니다. 시작 전 방장이 인원과 꽝 수를 설정합니다.</p><button class="primary" type="submit">방 만들기</button></form></div><div class="tool-card room-list-card"><h2>대기방 목록</h2><div class="room-list" aria-live="polite"><div class="empty">대기방을 불러오는 중입니다.</div></div></div></div>`;
    find('#room-login-button')?.addEventListener('click',onAuth);const form=find('#room-create-form');if(form){bindCapacity(form);form.onsubmit=event=>{event.preventDefault();void change(()=>api.create(Number(form.elements.capacity.value),Number(form.elements.losers.value),Number(form.elements.map.value)));};}}
  async function refreshList(){if(!alive()||current||!approved(actor))return;const id=++generation;try{const rooms=await api.list();if(!alive()||id!==generation||current)return;const list=find('.room-list');const content=rooms.length?rooms.map(room=>`<div class="room-list-item"><div><strong>${esc(room.host)}님의 마블룰렛</strong><span>참여 ${room.count}/${room.capacity}명</span></div><button class="secondary" type="button" data-room-code="${esc(room.code)}" aria-label="${esc(room.host)}님의 방 입장" ${room.count>=room.capacity?'disabled':''}>입장</button></div>`).join(''):'<div class="empty">열려 있는 대기방이 없습니다.</div>';if(list.innerHTML!==content){list.innerHTML=content;for(const button of list.querySelectorAll('[data-room-code]'))button.onclick=()=>void change(()=>api.join(button.dataset.roomCode));}}catch(failure){if(alive()&&id===generation)error(friendly(failure));}}
  async function change(action){if(busy||!alive())return;busy=true;generation++;error('');try{const room=await action();if(!alive())return;current=room;syncClock(room);drawRoom();}catch(failure){if(alive())error(friendly(failure));}finally{busy=false;}}
  function syncClock(room){if(room.start_at&&clockRound===room.start_at)return;clockOffset=room._clockOffset??(Date.parse(room.server_time)-Date.now());clockRound=room.start_at;}
  function drawRoom(){find('#marble-lobby').hidden=true;find('#marble-room').hidden=false;const me=current.players.find(player=>player.id===actor?.id),ready=current.players.filter(player=>player.ready).length;find('#marble-room').innerHTML=`<div class="room-heading"><div><span class="room-eyebrow">${esc(current.players.find(player=>player.id===current.host_id)?.nickname||'방장')}님의 방</span><h2>${esc(current.title)}</h2><p>${esc(current.map_name||'Wheel of fortune')}</p><p>준비 ${ready}/${current.capacity}명 · 인원이 모두 입장하고 준비하면 시작합니다.</p></div><div class="room-heading-buttons"><button type="button" class="text-button" id="room-leave">나가기</button></div></div>${current.host_id===actor?.id&&current.phase==='waiting'?`<form class="tool-card room-settings" id="room-settings-form">${settingsFields(current.capacity,current.losers,current.map_index??0)}<button class="secondary" type="submit">설정 변경</button></form>`:''}<div class="room-player-grid">${Array.from({length:current.capacity},(_,index)=>{const player=current.players[index];return player?`<div class="room-player" data-ready="${player.ready}"><span class="room-avatar" style="--player-colour:${colours[index]}">${esc(player.nickname[0])}</span><strong class="member-identity">${memberName(player.nickname,player.team,player.region,player.staff_role)}</strong><span class="room-ready-status">${player.ready?'준비 완료':'준비 중'}${player.id===current.host_id?' · 방장':''}</span></div>`:'<div class="room-player empty-seat"><span>+</span><p>입장 대기</p></div>';}).join('')}</div><div class="room-ready-bar"><p id="room-stage" role="status"></p><button class="primary" type="button" id="room-ready" aria-pressed="${Boolean(me?.ready)}">${me?.ready?'준비 취소':'준비'}</button></div><div id="room-game"></div>`;
    const settingsForm=find('#room-settings-form');if(settingsForm){bindCapacity(settingsForm);settingsForm.onsubmit=event=>{event.preventDefault();void change(()=>api.settings(current.id,Number(settingsForm.elements.capacity.value),Number(settingsForm.elements.losers.value),Number(settingsForm.elements.map.value)));};}
    find('#room-ready').disabled=!me||['running','finished','closed'].includes(current.phase);find('#room-ready').onclick=()=>void change(()=>api.ready(current.id,!me.ready));find('#room-leave').onclick=async()=>{if(busy)return;busy=true;generation++;try{await api.leave(current.id);current=null;boardKey='';stopEffects();find('#marble-room').hidden=true;find('#marble-lobby').hidden=false;await refreshList();}catch(failure){if(alive())error(friendly(failure));}finally{busy=false;}};boardKey='';tick();}
  function prepare(){
    if(!current||!Number.isInteger(current.simulation_seed))return;
    const key=`${current.id}:${current.simulation_seed}:${current.capacity}:${current.map_index}`;
    if(preparedKey===key)return;
    preparedKey=key;preparedMovie=null;stopEffects();boardKey='';
    prepareTask=(async()=>{try{engine=await import('./marble-engine.js?v=20261022-marble-motion-v3');const room=current,movie=await engine.prepareMarbleMovie(room.capacity,room.simulation_seed,signal,room.map_index??0);if(!alive()||preparedKey!==key)return;preparedMovie=movie;error('');tick();if(room.host_id===actor?.id&&room.playback_version===2){try{const updated=await api.duration(room.id,room.simulation_seed,Math.max(10000,Math.round(movie.duration*1000)));if(alive()&&preparedKey===key&&current?.simulation_seed===room.simulation_seed&&updated.revision>=current.revision){current=updated;syncClock(updated);tick();}}catch{if(alive()&&preparedKey===key&&current?.simulation_seed===room.simulation_seed)error('경기 시간 동기화를 다시 시도하려면 방을 나간 뒤 다시 입장해 주세요.');}}}catch(failure){if(alive()&&preparedKey===key&&failure?.name!=='AbortError'){preparedKey='';error('구슬 경기를 불러오지 못했어요. 잠시 후 다시 시도합니다.');}}})();
  }
  function mountBoard(){
    if(!preparedMovie||!current.round)return;
    const duration=current.playback_version===2?(current.playback_duration_ms||preparedMovie.duration*1000):Date.parse(current.finish_at)-Date.parse(current.start_at),holder=find('#room-game'),key=`${current.id}:${current.start_at}:${duration}`;
    if(boardKey===key&&holder.querySelector('canvas'))return;
    stopEffects();boardKey=key;const round=current.round,roomId=current.id,start=current.start_at,finish=current.finish_at;
    holder.innerHTML=`<div class="room-game-card marble-game-card"><canvas class="marble-canvas" aria-label="입장한 회원들이 함께 참여하는 구슬 경기"></canvas><div class="room-results" aria-live="polite">${round.ranking.map((player,rank)=>`<div data-marble-result="${player}" data-outcome="${rank>=round.players.length-current.losers?'lose':'pass'}" hidden><span>${rank+1}. ${esc(round.players[player].name)}</span><strong>${rank>=round.players.length-current.losers?'꽝':'통과'}</strong></div>`).join('')}</div>${ladderGiftLinks()}<p class="marble-attribution">Physics and maps based on <a href="https://github.com/lazygyu/roulette" target="_blank" rel="noopener noreferrer">Marble Roulette by lazygyu</a> · <a href="./marble-LICENSE.txt" target="_blank" rel="noopener noreferrer">MIT</a></p></div>`;
    const serverNow=Date.now()+clockOffset,animationNow=performance.now();
    stopEffects=engine.playMarbleMovie(holder.querySelector('canvas'),preparedMovie,round,()=>Math.max(0,Math.min(1,(serverNow+performance.now()-animationNow-Date.parse(start))/duration)),arrived=>{
      if(!alive()||current.id!==roomId||current.start_at!==start)return;
      for(const row of holder.querySelectorAll('[data-marble-result]'))row.hidden=!arrived.includes(Number(row.dataset.marbleResult));
      holder.querySelector('.ladder-gift-links').hidden=arrived.length<round.players.length;
    },onFrame);
  }
  function tick(){
    if(!alive()||!current)return;
    const stage=find('#room-stage');if(current.phase==='closed'){stopEffects();stage.textContent='대기방이 종료되었습니다.';find('#room-ready').disabled=true;return;}
    prepare();
    if(!current.start_at){stage.textContent='모두 준비되면 5초 후 함께 시작합니다.';return;}
    const now=Date.now()+clockOffset,remaining=Math.ceil((Date.parse(current.start_at)-now)/1000);
    if(remaining>0){stage.innerHTML=`<span class="room-countdown">${remaining}</span> 게임 시작까지`;return;}
    find('#room-ready').disabled=true;
    if(!current.round||!preparedMovie){stage.textContent='구슬 경기를 준비하고 있어요.';return;}
    mountBoard();const duration=current.playback_version===2?(current.playback_duration_ms||preparedMovie.duration*1000):Date.parse(current.finish_at)-Date.parse(current.start_at),seconds=Math.max(0,Math.ceil((Date.parse(current.start_at)+duration-now)/1000));stage.textContent=seconds?`구슬 경기 진행 중 · ${seconds}초`:'모든 결과가 공개되었습니다.';
  }

  async function poll(){if(!alive()||busy)return;if(!current){await refreshList();return;}const id=++generation;try{const room=await api.get(current.id);if(!alive()||id!==generation)return;const redraw=room.revision!==current.revision||room.phase!==current.phase;current=room;syncClock(room);if(redraw)drawRoom();else tick();}catch(failure){if(alive()&&id===generation){error(friendly(failure));find('#room-ready')?.setAttribute('disabled','');}}}
  const onVisibility=()=>{tick();};document.addEventListener('visibilitychange',onVisibility);
  const timer=setInterval(tick,150),pollTimer=setInterval(()=>void poll(),1500);signal?.addEventListener('abort',()=>{clearInterval(timer);clearInterval(pollTimer);stopEffects();document.removeEventListener('visibilitychange',onVisibility);generation++;if(current)void api.leave(current.id).catch(()=>{});},{once:true});
  lobby();await refreshList();const code=new URLSearchParams(location.hash.split('?')[1]).get('room');if(alive()&&approved(actor)&&code)await change(()=>api.join(code.toUpperCase()));
}
